const embRes = $input.first().json;
const body = $('Webhook Consulta').first().json.body || {};
const pregunta = body.pregunta || '';
const proyecto = body.proyecto || null;
const n_results = body.n_results || 5;

if (!embRes.data || !embRes.data[0]) {
  throw new Error(`Embedding response invalid: ${JSON.stringify(embRes).slice(0,300)}`);
}

const payload = {
  query_embeddings: [embRes.data[0].embedding],
  n_results,
  include: ['documents','metadatas','distances']
};
if (proyecto) payload.where = { proyecto };

return [{ json: { pregunta, proyecto, n_results, chroma_payload: payload } }];

const chromaRes = $input.first().json;
const body = $('Webhook Consulta').first().json.body || {};
const pregunta = body.pregunta || '';
const proyecto = body.proyecto || null;

const ids = (chromaRes.ids && chromaRes.ids[0]) || [];
const docs = (chromaRes.documents && chromaRes.documents[0]) || [];
const metas = (chromaRes.metadatas && chromaRes.metadatas[0]) || [];
const dists = (chromaRes.distances && chromaRes.distances[0]) || [];

if (ids.length === 0) {
  return [{ json: {
    skip_llm: true,
    pregunta, proyecto,
    respuesta: 'No encontre eso en tus fuentes.',
    citas: [], modo: 'real'
  }}];
}

const citas = ids.map((id, i) => ({
  archivo: metas[i]?.archivo,
  pagina: metas[i]?.pagina_aprox,
  total_paginas: metas[i]?.total_paginas,
  chunk_index: metas[i]?.chunk_index,
  proyecto: metas[i]?.proyecto,
  distancia: Number((dists[i] || 0).toFixed(4)),
  extracto: (docs[i] || '').slice(0, 600)
}));

const contexto = ids.map((id, i) =>
  `[${i+1}] (archivo: ${metas[i]?.archivo}, pag ~${metas[i]?.pagina_aprox}/${metas[i]?.total_paginas})\n${docs[i]}`
).join('\n\n---\n\n');

const system = `Eres CoWorkerIA, asistente de conocimiento del usuario. Respondes EXCLUSIVAMENTE basandote en los pasajes que se te entregan a continuacion.

REGLAS NO NEGOCIABLES:
1. NUNCA inventes informacion. Si los pasajes no contienen la respuesta, di exactamente: "No encontre eso en tus fuentes."
2. SIEMPRE cita la fuente al final de cada afirmacion factual, en formato [archivo, pag. N], donde N es el numero del pasaje.
3. Se conciso y directo. Sin introducciones ni cierres innecesarios.
4. Si los pasajes son contradictorios entre si, senala explicitamente la contradiccion al usuario.
5. Tu rol incluye ser un sparring critico: si detectas una debilidad o supuesto no verificado en la pregunta del usuario, comentalo brevemente al final bajo el encabezado "Observacion critica:".`;

const user = `Pregunta del usuario: ${pregunta}\n\nPasajes recuperados (ordenados por similitud):\n\n${contexto}\n\nResponde usando solo estos pasajes.`;

const llmPayload = {
  model: $env.LLM_MODEL || 'anthropic/claude-sonnet-4',
  messages: [
    { role: 'system', content: system },
    { role: 'user', content: user }
  ],
  max_tokens: 800,
  temperature: 0.2
};

return [{ json: { skip_llm: false, pregunta, proyecto, citas, llm_payload: llmPayload, modo: 'real' }}];

const llmRes = $input.first().json;
const prev = $('Build LLM prompt').first().json;
const respuesta = llmRes.choices?.[0]?.message?.content || '(LLM no devolvio respuesta)';
return [{ json: {
  pregunta: prev.pregunta,
  proyecto: prev.proyecto,
  respuesta,
  citas: prev.citas,
  modo: prev.modo,
  usage: llmRes.usage
}}];
